import{_ as e,c as r,o as i,ae as t}from"./chunks/framework.CHDT0Kbg.js";const m=JSON.parse('{"title":"プライバシーポリシー","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/privacy-policy.md","filePath":"ja/guide/privacy-policy.md","lastUpdated":1795170900000}'),o={name:"ja/guide/privacy-policy.md"};function l(c,a,n,s,h,d){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="プライバシーポリシー" tabindex="-1">プライバシーポリシー <a class="header-anchor" href="#プライバシーポリシー" aria-label="Permalink to &quot;プライバシーポリシー&quot;">​</a></h1><p>Persim が収集する情報と、端末に残る情報。</p><h2 id="アカウント不要、クラウドプロフィールなし" tabindex="-1">アカウント不要、クラウドプロフィールなし <a class="header-anchor" href="#アカウント不要、クラウドプロフィールなし" aria-label="Permalink to &quot;アカウント不要、クラウドプロフィールなし&quot;">​</a></h2><p>Persim はログインを求めず、オンラインアカウントも作成しません。履歴、ブックマーク、開いているタブ、ダウンロード、Cookie は Mac 上に保存されます。</p><h2 id="ページ表示に使う情報" tabindex="-1">ページ表示に使う情報 <a class="header-anchor" href="#ページ表示に使う情報" aria-label="Permalink to &quot;ページ表示に使う情報&quot;">​</a></h2><p>他のブラウザーと同様、開いたサイトのアドレスをそのサイトに送信します。Persim 自身が閲覧履歴をサーバーへアップロードすることはありません。</p><h2 id="オン・オフできるネットワーク機能" tabindex="-1">オン・オフできるネットワーク機能 <a class="header-anchor" href="#オン・オフできるネットワーク機能" aria-label="Permalink to &quot;オン・オフできるネットワーク機能&quot;">​</a></h2><ul><li>広告ブロックの購読はルール一覧を更新します。更新に失敗しても保存済みのルールは動作し続けます。</li><li>ユーザースクリプトやダウンロードファイルは、あなたが求めたときだけ取得します。</li><li>アドレスバーへの入力では、選択した検索エンジンから候補を取得します。</li></ul><h2 id="ローカルの権限" tabindex="-1">ローカルの権限 <a class="header-anchor" href="#ローカルの権限" aria-label="Permalink to &quot;ローカルの権限&quot;">​</a></h2><p>カメラ、マイク、ファイルへのアクセスはサイトごとに記憶され、設定で変更できます。位置情報と通知は macOS が管理します。プライベートウィンドウ（⌘⇧N）は履歴やセッションに残りません。</p><h2 id="サードパーティのサイト" tabindex="-1">サードパーティのサイト <a class="header-anchor" href="#サードパーティのサイト" aria-label="Permalink to &quot;サードパーティのサイト&quot;">​</a></h2><p>訪問するサイトは他社が運営し、それぞれのプライバシーポリシーに従います。Persim の内蔵ページはあなたを追跡しません。</p><h2 id="お問い合わせ" tabindex="-1">お問い合わせ <a class="header-anchor" href="#お問い合わせ" aria-label="Permalink to &quot;お問い合わせ&quot;">​</a></h2><p>プライバシーに関するご質問：<strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong>。</p>',14)])])}const u=e(o,[["render",l]]);export{m as __pageData,u as default};
